<script setup lang="ts">
import { computed, ref, watch } from "vue";
import { ArrowLeft, ArrowUp, Check, ChevronDown, FileText, Folder, Image, Music2, Network, Pause, Pencil, Play, Plus, Presentation, RefreshCw, Search, Sparkles, Table2, Trash2, Video, WandSparkles, X } from "@lucide/vue";
export type ChatView = "home" | "plugins" | "automations" | "ppt" | "cluster" | "research" | "document" | "website" | "sheet" | "project";
const props = defineProps<{ view: ChatView; connected: boolean }>();
const emit = defineEmits<{ submit: [content: string]; navigate: [view: ChatView]; openProject: [] }>();
type ScheduleType = "daily" | "weekly" | "monthly";
type Automation = { id: string; name: string; frequency: string; prompt: string; enabled: boolean; lastRun: string; nextRun: string; scheduleType?: ScheduleType; scheduleTime?: string; scheduleDay?: number };
const prompt = ref(""); const pptCategory = ref("全部"); const pluginCategory = ref("全部插件"); const selectedTemplate = ref(0); const projectName = ref(""); const projectCreated = ref(false); const automationFormOpen = ref(false); const automationName = ref(""); const automationScheduleType = ref<ScheduleType>("daily"); const automationTime = ref("09:00"); const automationDay = ref(1); const automationPrompt = ref(""); const editingAutomationId = ref<string | null>(null); const automationNotice = ref(""); const automationFilter = ref<"all" | "enabled" | "paused">("all"); const pluginQuery = ref(""); const pluginTab = ref<"插件" | "技能">("插件"); const installed = ref(new Set(["图像生成", "音频生成"]));
const automationStorageKey = "sztucode.automations";
const automations = ref<Automation[]>(loadAutomations());

function loadAutomations(): Automation[] {
  try { return JSON.parse(localStorage.getItem(automationStorageKey) ?? "[]") as Automation[]; } catch { return []; }
}
function persistAutomations() { localStorage.setItem(automationStorageKey, JSON.stringify(automations.value)); }
const visibleAutomations = computed(() => automations.value.filter((item) => automationFilter.value === "all" || (automationFilter.value === "enabled" ? item.enabled : !item.enabled)));
const weekdays = ["周日", "周一", "周二", "周三", "周四", "周五", "周六"];
const scheduleSummary = computed(() => automationScheduleType.value === "daily" ? `每天 ${automationTime.value}` : automationScheduleType.value === "weekly" ? `每${weekdays[automationDay.value]} ${automationTime.value}` : `每月 ${automationDay.value} 日 ${automationTime.value}`);
function nextScheduledRun(type: ScheduleType, time: string, day: number): string { const [hour, minute] = time.split(":").map(Number); const now = new Date(); const next = new Date(now); next.setSeconds(0, 0); next.setHours(hour, minute, 0, 0); if (type === "daily" && next <= now) next.setDate(next.getDate() + 1); if (type === "weekly") { let offset = (day - now.getDay() + 7) % 7; if (!offset && next <= now) offset = 7; next.setDate(now.getDate() + offset); } if (type === "monthly") { next.setDate(Math.min(day, new Date(next.getFullYear(), next.getMonth() + 1, 0).getDate())); if (next <= now) { next.setMonth(next.getMonth() + 1, 1); next.setDate(Math.min(day, new Date(next.getFullYear(), next.getMonth() + 1, 0).getDate())); } } return next.toLocaleString("zh-CN", { month: "numeric", day: "numeric", weekday: "short", hour: "2-digit", minute: "2-digit" }); }
function resetAutomationForm() { automationName.value = ""; automationScheduleType.value = "daily"; automationTime.value = "09:00"; automationDay.value = 1; automationPrompt.value = ""; editingAutomationId.value = null; automationFormOpen.value = false; }
function openAutomationForm(item?: Automation) { editingAutomationId.value = item?.id ?? null; automationName.value = item?.name ?? ""; automationScheduleType.value = item?.scheduleType ?? (item?.frequency.includes("每周") ? "weekly" : item?.frequency.includes("每月") ? "monthly" : "daily"); automationTime.value = item?.scheduleTime ?? item?.frequency.match(/\d{2}:\d{2}/)?.[0] ?? "09:00"; automationDay.value = item?.scheduleDay ?? (automationScheduleType.value === "weekly" ? Math.max(0, weekdays.findIndex((day) => item?.frequency.includes(day))) : Number(item?.frequency.match(/每月\s*(\d+)/)?.[1] ?? 1)); automationPrompt.value = item?.prompt ?? ""; automationFormOpen.value = true; automationNotice.value = ""; }
function saveAutomation() { const name = automationName.value.trim(); const taskPrompt = automationPrompt.value.trim(); if (!name || !taskPrompt) return; const type = automationScheduleType.value; const day = automationDay.value; const item: Automation = { id: editingAutomationId.value ?? crypto.randomUUID(), name, frequency: scheduleSummary.value, prompt: taskPrompt, enabled: true, lastRun: "尚未运行", nextRun: nextScheduledRun(type, automationTime.value, day), scheduleType: type, scheduleTime: automationTime.value, scheduleDay: day }; const index = automations.value.findIndex((task) => task.id === item.id); if (index >= 0) automations.value[index] = { ...automations.value[index], ...item }; else automations.value.unshift(item); persistAutomations(); automationNotice.value = editingAutomationId.value ? "任务已更新" : "任务已创建"; resetAutomationForm(); }
function toggleAutomation(item: Automation) { item.enabled = !item.enabled; persistAutomations(); }
function removeAutomation(item: Automation) { if (!window.confirm(`删除自动化任务“${item.name}”？`)) return; automations.value = automations.value.filter((task) => task.id !== item.id); persistAutomations(); }
function runAutomation(item: Automation) { if (!props.connected) { automationNotice.value = "本地服务未连接，暂时无法运行任务"; return; } item.lastRun = new Date().toLocaleString("zh-CN", { hour: "2-digit", minute: "2-digit" }); automationNotice.value = `已提交“${item.name}”`; persistAutomations(); emit("submit", item.prompt); }
const viewConfig = computed(() => ({ ppt: ["输入你想创作的 PPT 主题","PPT","选择模板"], cluster: ["给 AI 团队派个活...","集群","集群精选案例"], research: ["描述你的问题，生成深度研究报告","深度研究","深度研究精彩案例"], document: ["上传文档进行编辑，或从零开始创建","文档","文档精选案例"], website: ["描述你的网站想法，风格、功能、数据库都可以","网站","选择模板"], sheet: ["上传表格进行分析，或从零开始创建","表格","表格精选案例"] }[props.view as "ppt" | "cluster" | "research" | "document" | "website" | "sheet"]));
const rawTemplates: Record<string, [string,string,string][]> = {
 ppt: [["自由风格","留白与柔和渐变","mist"],["静青尽调","并购尽职调查报告","blueprint"],["粉彩推导","连续时间生成建模","sky"],["季度复盘","关键指标与增长洞察","night"],["一网通办","服务运行复盘报告","paper"],["年度经营","2026 经营报告","cream"]],
 cluster: [["黑洞：GARGANTUA","交互式宇宙实验","space"],["3D 复古打字机","产品创意与实时渲染","typewriter"],["Bloomberg 风格看板","全球股市数据终端","terminal"]],
 research: [["推理芯片：四十二年周期","产业与技术路线研究","research-a"],["交互式论文：Attention Residuals","论文解读与可视化","research-b"],["船运：不是一个周期","行业数据深度拆解","research-c"]],
 document: [["比亚迪投资简报","市场表现与财务分析","doc-a"],["SCI 科研论文写作","标准学术论文结构","doc-b"],["中国石油业绩简报","经营数据可视化","doc-c"]],
 website: [["赛博雨幕","记忆实验室","web-a"],["艺术藏馆","伍尔芙的房间","web-b"],["光影空间","沉浸式建筑展览","web-c"],["静谧旅店","精品酒店主页","web-d"],["行星地平线","未来主题展示站","web-e"],["视觉档案","网格式艺术作品集","web-f"]],
 sheet: [["个人健康年度复盘","健康趋势与运动分析","sheet-a"],["脑科学分析表","实验数据与分布研究","sheet-b"],["Hermès 20 年经营全景表","长期财务表现","sheet-c"]]
};
const templates = computed(() => (rawTemplates[props.view] ?? []).map(([title, subtitle, tone]) => ({ title, subtitle, tone })));
const plugins = [["灵动报告","把静态报告变成灵动、鲜活的网页","效率办公","report"],["金融投资分析","二级市场研究与投资组合工作流","金融","finance"],["投资银行私募股权","投行与私募股权一级市场工作流","金融","bank"],["企业财务会计","企业财务与会计工作流插件","金融","accounting"],["灵感池","给创意工作者的设计灵感库","创意设计","idea"],["国家及行业标准查询","查询国家标准与行业标准","效率办公","standard"],["视频生成","根据文字描述生成高质量视频","创意设计","video"],["图像生成","根据文字描述生成高质量图像","创意设计","image"],["音频生成","根据文字描述生成高质量音频","创意设计","audio"],["万得金融数据服务","专业全面的金融数据基础设施","金融","wind"],["国际组织官方数据","查询 WHO、FAO 等公开数据","效率办公","global"],["Stripe","连接账户并查看客户与余额","效率办公","stripe"]] as const;
const filteredPlugins = computed(() => plugins.filter(item => (pluginCategory.value === "全部插件" || item[2] === pluginCategory.value) && (!pluginQuery.value || (item[0] + item[1]).toLowerCase().includes(pluginQuery.value.toLowerCase()))));
function submit() { const value = prompt.value.trim(); if (!value) return; emit("submit", value); prompt.value = ""; }
// 回车直接发送；Ctrl/Shift/Alt + 回车保留默认换行行为，且忽略中文输入法候选确认
function onComposerKeydown(event: KeyboardEvent) { if (event.key !== "Enter" || event.isComposing) return; if (event.shiftKey || event.ctrlKey || event.metaKey || event.altKey) return; event.preventDefault(); submit(); }
function togglePlugin(name: string) { const next = new Set(installed.value); next.has(name) ? next.delete(name) : next.add(name); installed.value = next; }
function createProject() { if (projectName.value.trim()) projectCreated.value = true; }
watch(() => props.view, () => { selectedTemplate.value = 0; if (props.view !== "project") projectCreated.value = false; });
</script>
<template>
 <section v-if="view === 'plugins'" class="chat-plugins">
  <header class="plugin-top"><nav><button v-for="tab in ['插件','技能'] as const" :key="tab" :class="{active: pluginTab === tab}" @click="pluginTab = tab">{{ tab }}</button></nav><button class="plugin-close" aria-label="返回对话" @click="emit('navigate','home')"><X :size="19" /></button></header>
  <div v-if="pluginTab === '插件'" class="plugin-content"><div class="plugin-heading"><div><h1>插件</h1><p>将外部工具接入 SztuCode，使它可以使用应用和服务完成任务</p></div><label><Search :size="15" /><input v-model="pluginQuery" placeholder="搜索插件" /></label></div><div class="plugin-categories"><button v-for="item in ['全部插件','金融','效率办公','代码开发','创意设计']" :key="item" :class="{active: pluginCategory === item}" @click="pluginCategory = item">{{ item }}</button></div><div class="plugin-grid"><button v-for="item in filteredPlugins" :key="item[0]" class="plugin-card" @click="togglePlugin(item[0])"><span class="plugin-logo" :class="'plugin-logo--' + item[3]"><Image v-if="item[3] === 'image'" :size="23" /><Video v-else-if="item[3] === 'video'" :size="23" /><Music2 v-else-if="item[3] === 'audio'" :size="23" /><Sparkles v-else :size="22" /></span><span><b>{{ item[0] }}</b><small>{{ item[1] }}</small></span><Check v-if="installed.has(item[0])" :size="16" /><Plus v-else class="plugin-add" :size="16" /></button></div></div>
  <div v-else class="skills-empty"><WandSparkles :size="46" /><h1>技能</h1><p>在对话中输入 <kbd>/</kbd> 快速调用已安装技能。</p><button @click="emit('navigate','home')">去对话中试试</button></div>
 </section>
 <section v-else-if="view === 'automations'" class="chat-automations"><header><div><h1>自动化</h1><p>按计划处理重复工作，任务保存在本机。</p></div><button @click="automationFormOpen ? resetAutomationForm() : openAutomationForm()"><X v-if="automationFormOpen" :size="16" /><Plus v-else :size="16" />{{ automationFormOpen ? '取消' : '新建任务' }}</button></header><p v-if="automationNotice" class="automation-notice" role="status">{{ automationNotice }}</p><form v-if="automationFormOpen" class="automation-form" @submit.prevent="saveAutomation"><div class="automation-form__heading"><div><b>{{ editingAutomationId ? '编辑自动化' : '创建自动化' }}</b><small>填写任务指令，然后设置重复执行计划</small></div></div><section class="automation-form__content"><h3>任务</h3><label>名称<input v-model="automationName" required autofocus placeholder="例如：每周项目进展汇总" /></label><label>执行内容<textarea v-model="automationPrompt" required rows="5" placeholder="详细描述每次运行需要完成的工作" /></label></section><section class="automation-form__schedule"><h3>执行计划</h3><div class="automation-schedule-tabs"><button v-for="item in [['daily','每天'],['weekly','每周'],['monthly','每月']]" :key="item[0]" type="button" :class="{ active: automationScheduleType === item[0] }" @click="automationScheduleType = item[0] as ScheduleType">{{ item[1] }}</button></div><div class="automation-schedule-fields"><label v-if="automationScheduleType === 'weekly'">星期<select v-model.number="automationDay"><option v-for="(day,index) in weekdays" :key="day" :value="index">{{ day }}</option></select></label><label v-else-if="automationScheduleType === 'monthly'">日期<select v-model.number="automationDay"><option v-for="day in 28" :key="day" :value="day">{{ day }} 日</option></select></label><label>时间<input v-model="automationTime" type="time" required /></label></div><div class="automation-schedule-summary"><span>下一次</span><b>{{ nextScheduledRun(automationScheduleType, automationTime, automationDay) }}</b><small>{{ scheduleSummary }}</small></div></section><footer><button type="button" @click="resetAutomationForm">取消</button><button type="submit" :disabled="!automationName.trim() || !automationPrompt.trim()">{{ editingAutomationId ? '保存修改' : '创建任务' }}</button></footer></form><template v-else><div v-if="automations.length" class="automation-toolbar"><span>{{ automations.length }} 个任务</span><nav><button v-for="item in [['all','全部'],['enabled','运行中'],['paused','已暂停']]" :key="item[0]" :class="{ active: automationFilter === item[0] }" @click="automationFilter = item[0] as typeof automationFilter">{{ item[1] }}</button></nav></div><div v-if="visibleAutomations.length" class="automation-list"><article v-for="item in visibleAutomations" :key="item.id" class="automation-card"><div class="automation-card__top"><span class="automation-status" :class="{ paused: !item.enabled }"><i />{{ item.enabled ? '运行中' : '已暂停' }}</span><div class="automation-card__actions"><button title="立即运行" @click="runAutomation(item)"><Play :size="14" /></button><button title="编辑" @click="openAutomationForm(item)"><Pencil :size="14" /></button><button title="删除" @click="removeAutomation(item)"><Trash2 :size="14" /></button></div></div><h2>{{ item.name }}</h2><p>{{ item.prompt }}</p><dl><div><dt>频率</dt><dd>{{ item.frequency }}</dd></div><div><dt>上次运行</dt><dd>{{ item.lastRun }}</dd></div><div><dt>下次运行</dt><dd>{{ item.nextRun }}</dd></div></dl><button class="automation-toggle" @click="toggleAutomation(item)"><Pause v-if="item.enabled" :size="13" />{{ item.enabled ? '暂停任务' : '恢复任务' }}</button></article></div><div v-else class="automation-empty"><RefreshCw :size="42" /><h2>{{ automations.length ? '没有匹配的任务' : '暂无自动化任务' }}</h2><p>{{ automations.length ? '切换筛选条件查看其他任务。' : '创建第一个任务，让重复工作自动运行。' }}</p><button v-if="!automations.length" @click="openAutomationForm"><Plus :size="15" />创建任务</button></div></template></section> <section v-else-if="view === 'project'" class="chat-project"><div v-if="!projectCreated" class="project-create-card"><h1>新建项目</h1><p>同一件事，都在这里聊</p><div class="project-folders"><span /><span /><button aria-label="选择本地文件夹" @click="emit('openProject')"><Folder :size="78" /><Plus :size="34" /></button><span /><span /></div><form @submit.prevent="createProject"><input v-model="projectName" autofocus placeholder="取个名字" /><button :disabled="!projectName.trim()">创建项目</button></form></div><div v-else class="project-success"><span><Check :size="30" /></span><h1>{{ projectName }} 已创建</h1><p>现在可以把相关对话、文档和资料都放进这个项目。</p><button @click="emit('navigate','home')">开始对话</button></div></section>
 <section v-else class="chat-workspace" :class="'chat-workspace--' + view"><button v-if="view !== 'home'" class="chat-tool-back" aria-label="返回通用问答" @click="emit('navigate','home')"><ArrowLeft :size="17" />通用问答</button><button class="upgrade-pill"><Music2 :size="16" />升级套餐</button><div class="dot-wordmark" aria-label="SztuCode"><span v-for="n in 72" :key="n" :class="{accent: [11,29,46,63].includes(n)}" /></div><form class="chat-composer" @submit.prevent="submit"><textarea v-model="prompt" :placeholder="viewConfig?.[0] || '输入 / 唤起插件和技能'" rows="3" @keydown="onComposerKeydown" /><div class="chat-toolbar"><button type="button" aria-label="添加附件"><Plus :size="20" /></button><button v-if="viewConfig" type="button" class="active-tool"><Presentation v-if="view === 'ppt'" :size="16" /><Network v-else-if="view === 'cluster'" :size="16" /><FileText v-else-if="view === 'document' || view === 'research'" :size="16" /><Table2 v-else-if="view === 'sheet'" :size="16" /><Image v-else :size="16" />{{ viewConfig[1] }}</button><span /><button type="button" class="model-button">K3 <small>进阶</small><ChevronDown :size="14" /></button><button class="chat-send" type="submit" :disabled="!prompt.trim() || !connected"><ArrowUp :size="20" /></button></div><button class="project-selector" type="button" @click="emit('navigate','project')"><Folder :size="16" />选择项目<ChevronDown :size="14" /></button></form>
  <div v-if="view === 'home'" class="quick-tools"><button v-for="item in [['ppt','PPT'],['cluster','集群'],['research','深度研究'],['document','文档'],['website','网站'],['sheet','表格']]" :key="item[0]" @click="emit('navigate', item[0] as ChatView)">{{ item[1] }}</button></div>
  <section v-else-if="viewConfig" class="template-section"><header><h2>{{ viewConfig[2] }}</h2><button v-if="view === 'sheet'" @click="selectedTemplate = (selectedTemplate + 1) % templates.length"><RefreshCw :size="15" />换一换</button></header><div v-if="view === 'ppt'" class="template-categories"><button v-for="item in ['全部','战略咨询','金融投资','工作汇报','宣传推广','学术研究']" :key="item" :class="{active: pptCategory === item}" @click="pptCategory = item">{{ item }}</button></div><div class="template-grid"><button v-for="(item,index) in templates" :key="item.title" :class="{selected: selectedTemplate === index}" @click="selectedTemplate = index"><span class="template-preview" :class="'template-preview--' + item.tone"><Check v-if="selectedTemplate === index" :size="18" /><b>{{ item.subtitle }}</b></span><strong>{{ item.title }}</strong></button></div></section><small v-if="view !== 'home'" class="ai-disclaimer">内容由 AI 生成，请仔细甄别</small>
 </section>
</template>
